import { google } from 'googleapis';
import { readFileSync } from 'fs';

const tokens = JSON.parse(readFileSync('/root/auth/calendar/tokens.json')).accounts.default;
const credentials = JSON.parse(readFileSync('/root/auth/calendar/credentials.json')).installed;

const oauth2Client = new google.auth.OAuth2(
  credentials.client_id,
  credentials.client_secret
);
oauth2Client.setCredentials(tokens);

const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

async function listEvents() {
  try {
    const res = await calendar.events.list({
      calendarId: 'primary',
      timeMin: '2026-01-01T00:00:00Z',
      timeMax: '2026-01-31T23:59:59Z',
      singleEvents: true,
      orderBy: 'startTime'
    });
    console.log(JSON.stringify(res.data.items, null, 2));
  } catch (err) {
    console.error(err.message);
  }
