import { readFileSync, writeFileSync } from 'fs';

const input = JSON.parse(readFileSync('/root/test_input.json', 'utf8'));

const results = [];

const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

function formatTime(hour, minute) {
    const ampm = hour >= 12 ? 'PM' : 'AM';
    const h = hour % 12 || 12;
    const hh = h < 10 ? '0' + h : h;
    const mm = minute < 10 ? '0' + minute : minute;
    return `${hh}:${mm} ${ampm}`;
}

// 1. John Smith: Jan 8th, 2026, 1 hour, 10:00 AM - 2:00 PM.
// Earliest: Jan 8th, 10:00 AM - 11:00 AM.
results.push({
    from: "john.smith@example.com",
    day: "Thursday",
    date: "January 08, 2026",
    time: "10:00 AM - 11:00 AM",
    duration: 1,
    messageId: "mock-msg-john-smith-12345"
});

// 2. Robert Wilson: Jan 8th - 9th, 2026, 1.5 hours, 11:00 AM - 3:00 PM PST.
// Earliest: Jan 8th, 11:00 AM - 12:30 PM.
results.push({
    from: "rwilson@example.consulting.net",
    day: "Thursday",
    date: "January 08, 2026",
    time: "11:00 AM - 12:30 PM",
    duration: 1.5,
    messageId: "mock-msg-robert-wilson-67890"
});

// 3. Amanda Lee: Jan 6th or 7th, 2026, 45 minutes, 9:30 AM - 11:30 AM.
// Earliest: Jan 6th, 09:30 AM - 10:15 AM.
results.push({
    from: "amanda.lee@example.hr-solutions.com",
    day: "Tuesday",
    date: "January 06, 2026",
    time: "09:30 AM - 10:15 AM",
    duration: 0.75, // 45 mins is 0.75 hours
    messageId: "mock-msg-amanda-lee-54321"
